def load_required_swanlab_api_key():
    """Load the dashboard credential without embedding it in the runner."""
    api_key = os.getenv("SWANLAB_API_KEY", "").strip()
    if not api_key:
        try:
            from kaggle_secrets import UserSecretsClient

            api_key = UserSecretsClient().get_secret("SWANLAB_API_KEY").strip()
        except Exception as exc:
            raise SystemExit(
                "SwanLab credential unavailable: set SWANLAB_API_KEY in the "
                "environment or configure the Kaggle Secret with that name"
            ) from exc
    if not api_key:
        raise SystemExit("SWANLAB_API_KEY is empty")
    return api_key

