def unique_input_file(pattern, label):
    candidates = sorted(input_root.glob(pattern))
    if len(candidates) != 1:
        raise SystemExit(
            f"Expected exactly one {label} under /kaggle/input, found "
            f"{len(candidates)}: {candidates}"
        )
    return candidates[0]


def find_manifest_bound_dataset():
    """Select the one corrected dataset root by its signed content manifest.

    Kaggle can retain stale files from an earlier upload in the same dataset
    version. Those files must not be allowed to compete with the corrected
    bundle, but multiple valid manifests remain an error.
    """
    manifest_candidates = sorted(input_root.glob("**/data_manifest.json"))
    matching = []
    for manifest_path in manifest_candidates:
        try:
            document = json.loads(manifest_path.read_text())
        except (OSError, json.JSONDecodeError):
            continue
        if document.get("manifest_sha256") != EXPECTED_DATA_MANIFEST_SHA256:
            continue
        root = manifest_path.parent
        files = {
            "train_data.pkl": root / "processed_datasets/train_data.pkl",
            "val_data.pkl": root / "processed_datasets/val_data.pkl",
            "asset_metadata.csv": root / "asset_metadata.csv",
        }
        if all(path.is_file() for path in files.values()):
            matching.append((manifest_path, root, files))

    if len(matching) != 1:
        raise SystemExit(
            "Expected exactly one corrected v1-beta data manifest under "
            f"/kaggle/input, found {len(matching)} valid manifests; "
            f"all candidates: {manifest_candidates}"
        )

    manifest_path, data_root, files = matching[0]
    stale_train = sorted(
        path for path in input_root.glob("**/processed_datasets/train_data.pkl")
        if path != files["train_data.pkl"]
    )
    stale_val = sorted(
        path for path in input_root.glob("**/processed_datasets/val_data.pkl")
        if path != files["val_data.pkl"]
    )
    stale_metadata = sorted(
        path for path in input_root.glob("**/asset_metadata.csv")
        if path != files["asset_metadata.csv"]
    )
    if stale_train or stale_val or stale_metadata:
        print(json.dumps({
            "ignored_stale_input_files": {
                "train_data.pkl": [str(path) for path in stale_train],
                "val_data.pkl": [str(path) for path in stale_val],
                "asset_metadata.csv": [str(path) for path in stale_metadata],
            },
            "selected_manifest": str(manifest_path),
        }, ensure_ascii=False, indent=2), flush=True)
    return data_root, files["train_data.pkl"], files["val_data.pkl"], files["asset_metadata.csv"]


data_root, data_file, val_file, metadata_file = find_manifest_bound_dataset()

def sha256(path):
    digest = hashlib.sha256()
    with path.open("rb") as handle:
        for chunk in iter(lambda: handle.read(1024 * 1024), b""):
            digest.update(chunk)
    return digest.hexdigest()

