def normalize_resume_position(segment, step, total_steps):
    """Map an observed completed segment to the next segment's step zero."""
    segment = int(segment)
    step = int(step)
    total_steps = int(total_steps)
    if step == total_steps:
        return segment + 1, 0
    return segment, step


if resume_state is not None:
    source_output_root = resume_state.parent.parent
    required_history = [
        "run.log", "metrics.jsonl", "progress.json", "experiment_manifest.json",
        "checkpoints/last_state.pt",
        "checkpoints/best_model/model.safetensors", "checkpoints/best_model/config.json",
    ]
    missing_history = [p for p in required_history if not (source_output_root / p).is_file()]
    if missing_history:
        raise SystemExit(f"Continuation output is incomplete at {source_output_root}: {missing_history}")
    try:
        resume_progress = json.loads((source_output_root / "progress.json").read_text())
    except (OSError, json.JSONDecodeError) as exc:
        raise SystemExit(f"Unable to read continuation progress.json at {source_output_root}: {exc}")
    if not isinstance(resume_progress, dict):
        raise SystemExit(f"Continuation progress.json is not an object at {source_output_root}")
    for key in ("current_segment", "current_step", "total_segments", "total_steps"):
        if key not in resume_progress:
            raise SystemExit(f"Continuation progress.json is missing {key}: {source_output_root}")
    if int(resume_progress["current_segment"]) < 1 or int(resume_progress["current_step"]) < 0:
        raise SystemExit(f"Continuation progress position is invalid: {resume_progress}")

    # progress.json is live observability and can be ahead of the last durable
    # checkpoint after a forced cancellation. Only last_state.pt determines
    # the optimizer/scheduler resume position.
    import torch

    resume_document = torch.load(
        resume_state, map_location="cpu", weights_only=False
    )
    for key in ("next_epoch", "optimizer", "scheduler", "model"):
        if key not in resume_document:
            raise SystemExit(f"Continuation last_state.pt is missing {key}")
    resume_checkpoint = {
        "next_epoch": int(resume_document["next_epoch"]),
        "resume_step": int(resume_document.get("resume_step", 0)),
        "effective_epochs": int(resume_document.get("effective_epochs", 0)),
        "best_val_loss": float(resume_document.get("best_val_loss", float("inf"))),
    }
    best_metric_source = source_output_root / "checkpoints/best_model/best_metric.json"
    if resume_checkpoint["next_epoch"] > 0 and not best_metric_source.is_file():
        raise SystemExit(
            "Continuation completed at least one segment but has no "
            "best_model/best_metric.json"
        )
    missing_derived_outputs = [
        path for path in (
            "summary.json",
            "checkpoints/last_model/model.safetensors",
            "checkpoints/last_model/config.json",
        )
        if not (source_output_root / path).is_file()
    ]
    del resume_document
    if resume_checkpoint["next_epoch"] < 0 or resume_checkpoint["resume_step"] < 0:
        raise SystemExit(
            f"Continuation checkpoint position is invalid: {resume_checkpoint}"
        )
    if resume_checkpoint["resume_step"] != 0:
        raise SystemExit(
            "v1-beta continuation is segment-level only; "
            "last_state.pt resume_step must be zero"
        )
    checkpoint_raw_position = (
        resume_checkpoint["next_epoch"] + 1,
        resume_checkpoint["resume_step"],
    )
    checkpoint_position = normalize_resume_position(
        *checkpoint_raw_position,
        resume_progress["total_steps"],
    )
    progress_raw_position = (
        int(resume_progress["current_segment"]),
        int(resume_progress["current_step"]),
    )
    progress_position = normalize_resume_position(
        resume_progress["current_segment"],
        resume_progress["current_step"],
        resume_progress["total_steps"],
    )
    observed_raw_position = (
        int(resume_progress["current_segment"]),
        int(resume_progress.get("observed_step", resume_progress["current_step"])),
    )
    if progress_position != checkpoint_position:
        recoverable_same_segment_rollback = (
            progress_raw_position[0] == checkpoint_raw_position[0]
            and progress_raw_position[1] > checkpoint_raw_position[1]
        )
        if not recoverable_same_segment_rollback:
            raise SystemExit(
                "Continuation progress and durable checkpoint disagree; refusing "
                f"an unsafe rollback: observed_next={progress_position}, "
                f"checkpoint_next={checkpoint_position}"
            )
        resume_recovery = {
            "type": "discard_uncheckpointed_progress",
            "observed_segment": progress_raw_position[0],
            "observed_step": progress_raw_position[1],
            "checkpoint_segment": checkpoint_raw_position[0],
            "checkpoint_step": checkpoint_raw_position[1],
            "discarded_steps": progress_raw_position[1] - checkpoint_raw_position[1],
            "reason": "Kaggle cancellation ended the process without a catchable signal",
        }
    elif (
        progress_raw_position[0] == checkpoint_raw_position[0]
        and observed_raw_position[0] == checkpoint_raw_position[0]
        and observed_raw_position[1] > checkpoint_raw_position[1]
    ):
        resume_recovery = {
            "type": "discard_uncheckpointed_progress",
            "observed_segment": observed_raw_position[0],
            "observed_step": observed_raw_position[1],
            "checkpoint_segment": checkpoint_raw_position[0],
            "checkpoint_step": checkpoint_raw_position[1],
            "discarded_steps": observed_raw_position[1] - checkpoint_raw_position[1],
            "reason": "Kaggle cancellation ended during an incomplete segment",
        }
    shutil.copytree(source_output_root, output_root, dirs_exist_ok=True)
    if resume_recovery is not None:
        metrics_path = output_root / "metrics.jsonl"
        retained_metrics = []
        discarded_metrics = 0
        for line in metrics_path.read_text().splitlines():
            try:
                item = json.loads(line)
            except json.JSONDecodeError:
                retained_metrics.append(line)
                continue
            metric_position = (
                int(item.get("segment") or 0),
                int(item.get("step") or 0),
            )
            if metric_position > checkpoint_raw_position:
                discarded_metrics += 1
            else:
                retained_metrics.append(line)
        metrics_path.write_text(
            "\n".join(retained_metrics) + ("\n" if retained_metrics else "")
        )
        resume_recovery["discarded_metric_rows"] = discarded_metrics
        recovery_path = output_root / "recovery_events.jsonl"
        with recovery_path.open("a") as handle:
            handle.write(json.dumps(resume_recovery, ensure_ascii=False) + "\n")
        resume_progress.update({
            "status": "recovered",
            "phase": "segment_replay",
            "current_segment": checkpoint_raw_position[0],
            "current_step": checkpoint_raw_position[1],
            "observed_step": checkpoint_raw_position[1],
        })
        (output_root / "progress.json").write_text(
            json.dumps(resume_progress, indent=2)
        )
