manifest_document = {
    "experiment": "A-share v1-beta two-speed Best-11",
    "data_manifest_sha256": data_manifest_sha256,
    "base_model_sha256": base_model_sha256,
    "parent_lineage": parent_lineage,
    "files": manifest_items,
    "config": {key: env[key] for key in manifest_keys},
}
manifest_path = output_root / "experiment_manifest.json"
if resume_state is not None:
    previous = json.loads(manifest_path.read_text()) if manifest_path.is_file() else None
    if not isinstance(previous, dict) or previous.get("data_manifest_sha256") != data_manifest_sha256:
        raise SystemExit("Continuation data manifest does not match the current dataset")
    previous_config = previous.get("config", {})
    for key in manifest_keys:
        if key in {"KRONOS_RESUME_TRAINING", "KRONOS_MAX_SEGMENTS_PER_RUN"}:
            continue
        if previous_config.get(key) != env[key]:
            raise SystemExit(f"Continuation config mismatch for {key}")
else:
    manifest_path.write_text(json.dumps(manifest_document, indent=2))

if resume_state is not None and any(
    path.startswith("checkpoints/last_model/") for path in missing_derived_outputs
):
    print(
        json.dumps({
            "resume_rebuild": "last_model",
            "reason": "derived Last export was absent after interruption",
        }, ensure_ascii=False),
        flush=True,
    )
    subprocess.run([
        "python", str(SOURCE_ROOT / "finetune/export_last_model.py"),
        "--output-root", str(output_root),
    ], env=env, check=True)


def init_swanlab():
    """Initialize the required cloud dashboard before training starts."""
    try:
        subprocess.run(["python", "-m", "pip", "install", "-q", "swanlab"], check=True)
        import swanlab

        swanlab.login(api_key=SWANLAB_API_KEY)
        run_id = os.getenv(
            "SWANLAB_RUN_ID", "kronos-v1-beta-twospeed-best11-120d-to-10d"
        )
        init_kwargs = {
            "project": os.getenv("SWANLAB_PROJECT", "finance"),
            "experiment_name": os.getenv(
                "SWANLAB_EXPERIMENT_NAME", output_name
            ),
            "id": run_id,
            "resume": "allow",
            "tags": ["kronos", "v1-beta", "two-speed", "best-11", "120d-to-10d"],
            "config": {
                "lookback": 120,
                "predict": 10,
                "data_manifest_sha256": data_manifest_sha256,
                "base_model_sha256": base_model_sha256,
                "parent_best_segment": (
                    None if parent_best_metric is None else parent_best_metric.get("segment")
                ),
                "resume": resume_state is not None,
                "output_name": output_name,
                "scheduler": "two_speed",
                "adaptation_peak_lr": 3e-6,
                "condition_peak_lr": 3e-5,
                "warmup_ratio": 0.005,
                "condition_fast_decay_ratio": 0.075,
                "condition_fast_decay_lr": 1e-5,
                "history_loss_weight": 0.02,
            },
        }
        workspace = os.getenv("SWANLAB_WORKSPACE", "roc_fu").strip()
        if workspace:
            init_kwargs["workspace"] = workspace
        run = swanlab.init(**init_kwargs)
        print(
            json.dumps({
                "swanlab": "enabled",
                "project": init_kwargs["project"],
                "experiment_name": init_kwargs["experiment_name"],
                "run_id": run_id,
                "resume": resume_state is not None,
            }, ensure_ascii=False),
            flush=True,
        )
        return run
    except Exception as exc:
        raise SystemExit(
            "SwanLab initialization failed before training: "
            f"{type(exc).__name__}: {exc}"
        ) from exc


def swanlab_log(run, data, step):
    if run is None:
        return
    try:
        run.log(data, step=int(step))
    except Exception as exc:
        print(
            f"SwanLab logging disabled after error: {type(exc).__name__}: {exc}",
            flush=True,
        )
        return None
    return run


TRAIN_LOG_RE = re.compile(
    r"Segment (\d+)/(\d+), Step (\d+)/(\d+).*?"
    r"Adaptation LR ([0-9.eE+-]+), Condition LR ([0-9.eE+-]+), "
    r"Loss: ([0-9.]+), "
    r"Forecast: ([0-9.]+), History: ([0-9.]+)"
)
VALIDATION_LOG_RE = re.compile(
    r"Validation Forecast/History/Full: ([0-9.]+) / ([0-9.]+) / ([0-9.]+)"
)
CONDITION_MONITOR_PREFIX = "Condition Monitor JSON: "
CONDITION_ABLATION_RE = re.compile(
    r"Validation Condition Full/None/Shuffled Forecast: "
    r"([0-9.eE+-]+) / ([0-9.eE+-]+) / ([0-9.eE+-]+); "
    r"Delta Full-None/Full-Shuffled: ([0-9.eE+-]+) / ([0-9.eE+-]+)"
)


def parse_swanlab_train_line(line):
    match = TRAIN_LOG_RE.search(line)
    if match is None:
        return None
    (
        segment, total_segments, step, total_steps,
        adaptation_lr, condition_lr, loss, forecast, history,
    ) = match.groups()
    return {
        "segment": int(segment),
        "total_segments": int(total_segments),
        "step": int(step),
        "total_steps": int(total_steps),
        "learning_rate": float(adaptation_lr),
        "adaptation_learning_rate": float(adaptation_lr),
        "condition_learning_rate": float(condition_lr),
        "loss": float(loss),
        "forecast_loss": float(forecast),
        "history_loss": float(history),
    }


def parse_swanlab_validation_line(line, segment, total_steps):
    match = VALIDATION_LOG_RE.search(line)
    if match is None:
        return None
    forecast, history, full = match.groups()
    return {
        "segment": int(segment),
        "forecast_loss": float(forecast),
        "history_loss": float(history),
        "full_loss": float(full),
        "step": int(total_steps),
    }


def parse_condition_monitor_line(line):
    marker = line.find(CONDITION_MONITOR_PREFIX)
    if marker < 0:
        return None
    payload = json.loads(line[marker + len(CONDITION_MONITOR_PREFIX):])
    if not isinstance(payload, dict) or not all(
        isinstance(value, (int, float)) for value in payload.values()
    ):
        raise ValueError("Condition monitor payload must contain numeric metrics")
    return payload


def parse_condition_ablation_line(line):
    match = CONDITION_ABLATION_RE.search(line)
    if match is None:
        return None
    full, none, shuffled, full_minus_none, full_minus_shuffled = map(float, match.groups())
    return {
        "full_forecast_loss": full,
        "none_forecast_loss": none,
        "shuffled_forecast_loss": shuffled,
        "full_minus_none_forecast_loss": full_minus_none,
        "full_minus_shuffled_forecast_loss": full_minus_shuffled,
    }


def backfill_swanlab(run):
    """Replay persisted metrics so every continuation shares one curve."""
    if run is None:
        return run
    history = output_root / "metrics.jsonl"
    if not history.is_file():
        return run
    try:
        count = 0
        for line in history.read_text().splitlines():
            try:
                item = json.loads(line)
            except json.JSONDecodeError:
                continue
            if item.get("type") not in {"train", "validation"}:
                continue
            total_steps = int(item.get("total_steps") or 1250)
            segment = int(item.get("segment") or 0)
            step = int(item.get("step") or 0)
            if item["type"] == "validation" and step == 0:
                # Validation is emitted after the segment's final train step.
                step = total_steps
            global_step = max(0, (segment - 1) * total_steps + step)
            prefix = item["type"]
            payload = {}
            for key, value in item.items():
                if (
                    key in {"updated_at", "type", "segment", "total_segments", "step", "total_steps"}
                    or not isinstance(value, (int, float))
                ):
                    continue
                normalized_key = key
                if prefix == "validation" and key == "full_sequence_loss":
                    normalized_key = "full_loss"
                elif prefix == "validation" and key == "loss":
                    normalized_key = "objective_loss"
                metric_prefix = prefix
                if prefix == "train" and (
                    key.startswith(("condition_", "adaptation_"))
                    or key in {
                        "trunk_input_norm", "sector_embedding_weight_norm",
                        "size_mlp_output_weight_norm",
                    }
                ) and key not in {"condition_learning_rate", "adaptation_learning_rate"}:
                    metric_prefix = "monitor"
                payload[f"{metric_prefix}/{normalized_key}"] = value
            payload["segment"] = segment
            swanlab_log(run, payload, global_step)
            count += 1
        print(f"SwanLab backfilled {count} historical metrics", flush=True)
    except Exception as exc:
        print(
            f"SwanLab history backfill skipped: {type(exc).__name__}: {exc}",
            flush=True,
        )
    return run


swanlab_run = backfill_swanlab(init_swanlab())

child = None
def forward_signal(signum, frame):
    if child is not None and child.poll() is None:
        child.send_signal(signum)
    print(f"Forwarded signal {signum} to training process", flush=True)

signal.signal(signal.SIGINT, forward_signal)
signal.signal(signal.SIGTERM, forward_signal)
child = subprocess.Popen(
    ["python", "-u", str(SOURCE_ROOT / "finetune/train_predictor.py")],
    env=env, stdout=subprocess.PIPE, stderr=subprocess.STDOUT,
    text=True, bufsize=1,
)
latest_segment = 0
latest_step = 0
latest_total_steps = 1250
for line in child.stdout:
    print(line, end="")
    train_record = parse_swanlab_train_line(line)
    if train_record is not None:
        latest_segment = train_record["segment"]
        latest_step = train_record["step"]
        latest_total_steps = train_record["total_steps"]
        swanlab_run = swanlab_log(
            swanlab_run,
            {
                "train/loss": train_record["loss"],
                "train/forecast_loss": train_record["forecast_loss"],
                "train/history_loss": train_record["history_loss"],
                "train/learning_rate": train_record["adaptation_learning_rate"],
                "train/adaptation_learning_rate": train_record["adaptation_learning_rate"],
                "train/condition_learning_rate": train_record["condition_learning_rate"],
                "segment": latest_segment,
            },
            (latest_segment - 1) * latest_total_steps + train_record["step"],
        )
    monitor_record = parse_condition_monitor_line(line)
    if monitor_record is not None and latest_segment > 0:
        swanlab_run = swanlab_log(
            swanlab_run,
            {
                f"monitor/{key}": value
                for key, value in monitor_record.items()
                if not key.endswith("parameter_count")
            },
            (latest_segment - 1) * latest_total_steps
            + latest_step,
        )
    validation_record = parse_swanlab_validation_line(
        line, latest_segment, latest_total_steps
    )
    if validation_record is not None and latest_segment > 0:
        swanlab_run = swanlab_log(
            swanlab_run,
            {
                "validation/objective_loss": (
                    validation_record["forecast_loss"]
                    + 0.02 * validation_record["history_loss"]
                ),
                "validation/forecast_loss": validation_record["forecast_loss"],
                "validation/history_loss": validation_record["history_loss"],
                "validation/full_loss": validation_record["full_loss"],
                "segment": latest_segment,
            },
            latest_segment * latest_total_steps,
        )
    ablation_record = parse_condition_ablation_line(line)
    if ablation_record is not None and latest_segment > 0:
        swanlab_run = swanlab_log(
            swanlab_run,
            {
                f"validation/condition_{key}": value
                for key, value in ablation_record.items()
            },
            latest_segment * latest_total_steps,
        )
return_code = child.wait()
if swanlab_run is not None:
    try:
        import swanlab
        swanlab.finish()
    except Exception as exc:
        print(f"SwanLab finish skipped: {type(exc).__name__}: {exc}", flush=True)
if return_code:
    raise subprocess.CalledProcessError(return_code, child.args)
subprocess.run([
    "python", str(SOURCE_ROOT / "finetune/export_last_model.py"),
    "--output-root", str(output_root),
], env=env, check=True)
required = [
    "run.log", "metrics.jsonl", "progress.json", "summary.json", "experiment_manifest.json",
    "checkpoints/last_state.pt", "checkpoints/best_model/model.safetensors",
    "checkpoints/best_model/config.json", "checkpoints/best_model/best_metric.json",
    "checkpoints/last_model/model.safetensors",
    "checkpoints/last_model/config.json",
]
missing = [str(output_root / path) for path in required if not (output_root / path).is_file()]
if missing:
    raise SystemExit(f"Output contract incomplete: {missing}")
print("v1-beta chunk completed and output contract verified", flush=True)
